const props = p => p.properties || {};
const text = v => !v ? "" : v.title ? v.title.map(t=>t.plain_text).join("") : v.rich_text ? v.rich_text.map(t=>t.plain_text).join("")
  : v.select ? (v.select.name||"") : v.status ? (v.status.name||"") : v.number!=null ? String(v.number) : v.checkbox!=null ? String(v.checkbox) : "";
const titleOf = p => { for (const k in props(p)) if (props(p)[k].type==="title") return text(props(p)[k]); return ""; };
const find = (p, re) => { for (const k in props(p)) if (re.test(k)) return text(props(p)[k]); return ""; };

const names = ["Router","Estimate","Scheduling","Finance","Content","Integrator"];
const last = {};
for (const i of $input.all().filter(i=>i.json.id)) { const a = find(i.json,/^agent$/i); if (!a) continue;
  const t = new Date(i.json.created_time); if (!last[a] || t > last[a].t) last[a] = { t, text: titleOf(i.json), status: find(i.json,/^status$/i).toLowerCase() }; }
const out = names.map(n => { const l = last[n]; if (!l) return { name:n, status:"idle", detail:"no activity yet" };
  const recent = Date.now() - l.t < 10*60*1000; const st = /await|wait|approval/.test(l.status) ? "waiting" : /fail|error/.test(l.status) ? "error" : recent ? "active" : "idle";
  return { name:n, status:st, detail:l.text }; });
return [{ json: { body: out } }];
